import time
from django.core.cache import cache
from django.db.models import Avg, Count
from .models import Book


POPULAR_CACHE_KEY = "books_popular"
STATS_CACHE_KEY = "books_stats"


def get_popular_books():
    """لیست کتاب‌های محبوب با cache."""
    def compute():
        return list(
            Book.objects.filter(is_active=True)
            .annotate(reviews_count=Count("reviews"))
            .order_by("-reviews_count", "-created_at")[:20]
            .values("id", "title", "price", "reviews_count")
        )
    return cache.get_or_set(POPULAR_CACHE_KEY, compute, timeout=600)


def get_dashboard_stats():
    """آمار داشبورد با cache کوتاه."""
    def compute():
        return {
            "total_books": Book.objects.filter(is_active=True).count(),
            "avg_price": float(
                Book.objects.aggregate(avg=Avg("price"))["avg"] or 0
            ),
        }
    return cache.get_or_set(STATS_CACHE_KEY, compute, timeout=300)


def invalidate_book_caches():
    """باطل کردن همه کش‌های مرتبط با کتاب."""
    cache.delete(POPULAR_CACHE_KEY)
    cache.delete(STATS_CACHE_KEY)


def get_or_compute(key, compute_fn, timeout=300, lock_timeout=10):
    """جلوگیری از Cache Stampede با lock."""
    data = cache.get(key)
    if data is not None:
        return data

    lock_key = f"{key}:lock"
    if cache.add(lock_key, "1", timeout=lock_timeout):
        try:
            data = compute_fn()
            cache.set(key, data, timeout=timeout)
            return data
        finally:
            cache.delete(lock_key)

    # یکی دیگر مشغول محاسبه است
    for _ in range(50):
        time.sleep(0.1)
        data = cache.get(key)
        if data is not None:
            return data
    return compute_fn()

