import pytest
from rest_framework import status
from .factories import BookFactory, UserFactory


@pytest.mark.django_db
class TestBookList:
    url = "/api/books/"

    def test_list_public(self, api_client):
        BookFactory.create_batch(3)
        response = api_client.get(self.url)
        assert response.status_code == status.HTTP_200_OK
        assert response.data["count"] == 3

    def test_list_empty(self, api_client):
        response = api_client.get(self.url)
        assert response.status_code == 200
        assert response.data["count"] == 0


@pytest.mark.django_db
class TestBookCreate:
    url = "/api/books/"

    def test_anonymous_401(self, api_client):
        response = api_client.post(self.url, {"title": "X"})
        assert response.status_code == status.HTTP_401_UNAUTHORIZED

    def test_user_can_create(self, auth_client):
        payload = {
            "title": "Clean Code",
            "author": 1,
            "isbn": "9780132350884",
            "price": "42.50",
            "published_at": "2008-08-01",
        }
        response = auth_client.post(self.url, payload, format="json")
        assert response.status_code in (201, 400)   # بسته به منطق

    @pytest.mark.parametrize("isbn,expected", [
        ("1234567890", 201),
        ("1234567890123", 201),
        ("ABC", 400),
        ("123", 400),
        ("", 400),
    ])
    def test_isbn_validation(self, staff_client, book, isbn, expected):
        payload = {
            "title": "Test",
            "author": book.author.id,
            "isbn": isbn,
            "price": "10.00",
            "published_at": "2020-01-01",
        }
        response = staff_client.post(self.url, payload, format="json")
        assert response.status_code == expected


@pytest.mark.django_db
class TestBookPermissions:
    def test_owner_can_edit(self, auth_client, book):
        response = auth_client.patch(
            f"/api/books/{book.id}/",
            {"title": "New"},
            format="json",
        )
        assert response.status_code in (200, 403)

    def test_other_cannot_edit(self, api_client, book):
        other = UserFactory()
        api_client.force_authenticate(user=other)
        response = api_client.patch(
            f"/api/books/{book.id}/",
            {"title": "Hacked"},
            format="json",
        )
        assert response.status_code in (403, 404)
